CREATE TABLE IF NOT EXISTS master_model (id INTEGER PRIMARY KEY AUTOINCREMENT, file_url TEXT NOT NULL, name TEXT NOT NULL, model_name TEXT NOT NULL, code TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, usecase_id INTEGER NOT NULL REFERENCES master_usecase(id) ON DELETE CASCADE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME);
CREATE UNIQUE INDEX IF NOT EXISTS uq_sqlite_master_model_code ON master_model(code);
